const form=document.getElementById("registerForm"),formMessage=document.getElementById("formMessage");function showError(e,t){e.classList.add("invalid");e.closest(".form-group").querySelector(".error").textContent=t}function clearError(e){e.classList.remove("invalid");e.closest(".form-group").querySelector(".error").textContent=""}function isValidEmail(e){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)}function isStrongPassword(e){const t=/[A-ZА-ЯӘІҢҒҮҰҚӨҺ]/.test(e),r=/\d/.test(e);return e.length>=8&&t&&r}form.addEventListener("submit",function(e){e.preventDefault();const t=document.getElementById("fullName"),r=document.getElementById("email"),s=document.getElementById("password"),o=document.getElementById("confirmPassword"),n=document.getElementById("terms"),a=document.getElementById("termsError");let i=!0;formMessage.textContent="";formMessage.className="form-message";a.textContent="";[t,r,s,o].forEach(clearError);t.value.trim().length<2&&(showError(t,"Аты-жөніңізді енгізіңіз."),i=!1);isValidEmail(r.value.trim())||(showError(r,"Дұрыс электрондық пошта енгізіңіз."),i=!1);isStrongPassword(s.value)||(showError(s,"Құпия сөз кемінде 8 таңбадан, бір бас әріптен және бір саннан тұрсын."),i=!1);o.value!==s.value&&(showError(o,"Құпия сөздер бірдей емес."),i=!1);n.checked||(a.textContent="Қолдану ережелерімен келісу қажет.",i=!1);i&&(formMessage.textContent="Тіркелу сәтті өтті! Бұл әзірше демонстрациялық нұсқа.",formMessage.classList.add("success"),form.reset())});document.querySelectorAll(".show-password").forEach(function(e){e.addEventListener("click",function(){const t=document.getElementById(e.dataset.target),r="password"===t.type;t.type=r?"text":"password";e.textContent=r?"Жасыру":"Көрсету"})});document.querySelectorAll(".form-group input").forEach(function(e){e.addEventListener("input",function(){clearError(e);formMessage.textContent=""})});
